import { Bubble } from '@refy-design/web';
import { Button } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function BubbleExample() {
  const [sent, setSent] = useState(false);
  return (
    <div style={stack}>
      <Bubble>Can we review the material today?</Bubble>
      {sent && <Bubble side="end">Yes, the review is confirmed.</Bubble>}
      <Button onClick={() => setSent(!sent)}>{sent ? 'Clear answer' : 'Reply'}</Button>
    </div>
  );
}
export function Example() {
  return <BubbleExample />;
}

import { Bubble } from '@refy-design/web';
import { ThemeProvider } from '@refy-design/web';
export function Example() {
  return (
    <ThemeProvider
      theme={{
        name: 'Bubble measures',
        tokens: {
          '--bubble-padding': '8px 16px',
          '--bubble-max-width': '320px',
          '--bubble-radius': '16px',
          '--bubble-tail-radius': '2px',
          '--bubble-end-border-width': '0px',
        },
      }}
    >
      <div style={{ display: 'grid', gap: 'var(--space-2)', maxWidth: 560 }}>
        <Bubble data-testid="bubble-start">
          Is the bike still available? I can pick it up this afternoon near the station.
        </Bubble>
        <Bubble side="end" data-testid="bubble-end">
          Yes, it is. I am home after 3 pm.
        </Bubble>
      </div>
    </ThemeProvider>
  );
}
